// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/TRITON.sol";

contract TotalSupplyDiscrepancyTest is Test {
    TRITON public token;
    address constant OWNER = address(1000);
    address constant USER = address(2000);
    address constant DEAD = 0x000000000000000000000000000000000000dEaD;

    function setUp() public {
        // Must run on BSC fork due to hardcoded router address
        if (block.chainid != 56) {
            console.log("Skipping test on non-BSC chain");
            return;
        }

        vm.startPrank(OWNER);
        token = new TRITON();

        // Configure trading and fees
        token.enableTrading();
        token.updateFees(
            0,   // buyDeadFees
            10,  // sellDeadFees
            0,   // buyMarketingFees
            0,   // sellMarketingFees
            0,   // buyLiquidityFee
            0,   // sellLiquidityFee
            0,   // buyRewardsFee
            0,   // sellRewardsFee
            0,   // buyDevFee
            0    // sellDevFee
        );
        token.setcooldowntimer(0);
        token.setGasPriceLimit(5); // Min value allowed: 5 GWEI
        vm.stopPrank();

        // Transfer tokens to test user
        uint256 transferAmount = 500 * 10**token.decimals();
        vm.prank(OWNER);
        token.transfer(USER, transferAmount);

        // Skip initial blocks
        vm.roll(block.number + 7);
    }

    function testTotalSupplyDiscrepancyAfterBurn() public {
        if (block.chainid != 56) return;

        // Pre-transfer state
        uint256 initialSupply = token.totalSupply();
        address pair = token.uniswapV2Pair();
        uint256 userBalance = token.balanceOf(USER);

        // Simulate sell (expected burn: 10% of userBalance)
        uint256 expectedBurn = userBalance * 10 / 100;
        vm.prank(USER);
        token.transfer(pair, userBalance); // Triggers deadFees during sell

        // Post-transfer state
        uint256 postSupply = token.totalSupply();
        uint256 deadBalance = token.balanceOf(DEAD);

        // Calculate sum of all balances
        uint256 balanceSum = 
            token.balanceOf(OWNER) +
            token.balanceOf(USER) +
            deadBalance +
            token.balanceOf(address(token)) +
            token.balanceOf(pair) +
            token.balanceOf(address(token.dividendTracker()));

        // Verify discrepancy
        assertEq(
            postSupply,
            initialSupply - expectedBurn,
            "Total supply not reduced correctly"
        );
        assertEq(
            deadBalance,
            expectedBurn,
            "Dead address balance not updated"
        );
        assertEq(
            balanceSum,
            initialSupply,
            "Sum of balances should remain unchanged"
        );
        assertTrue(
            postSupply != balanceSum,
            "Total supply should not match sum of balances"
        );
    }
}
